 patch.append(f'diff --git a/{path} b/{path}\n'+('new file mode 100644\n'if isnew else''));patch.append(''.join(difflib.unified_diff(old.splitlines(True),current.splitlines(True),fromfile='/dev/null'if isnew else'a/'+path,tofile='b/'+path)))
